```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel2-service') AND span_name='GET /api/v1/travel2service/admin_trip' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "travel2 admin_trip server p95 is about 1917 ms in the abnormal period (normal about 28 ms)."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50, approx_quantile(duration,0.95)/1e6 p95 FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='GET /api/v1/travel2service/admin_trip' AND duration>300000000) AND service_name='ts-travel2-service' GROUP BY 1,2,3 ORDER BY p95 DESC",
          "claim": "In slow travel2 traces, its outbound GET client spans take hundreds of ms while its DB spans stay under 1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name child_svc, c.span_name, c.attr_span_kind, p.service_name parent_svc, p.span_name parent_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 p50, approx_quantile(c.duration,0.95)/1e6 p95 FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='GET /api/v1/travel2service/admin_trip' AND duration>300000000) AND c.service_name='ts-route-service' AND p.service_name='ts-travel2-service' GROUP BY ALL",
          "claim": "Route-service server spans called from travel2 finish in about 2 ms, so the delay precedes the callee."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_pod_name pod, service_name, attr_span_kind, date_trunc('minute', time) m, count(*) n, approx_quantile(duration,0.5)/1e6 p50, approx_quantile(duration,0.95)/1e6 p95 FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='GET' AND attr_span_kind='Client' GROUP BY ALL ORDER BY m, pod",
          "claim": "Slow outbound GET calls come from one travel2 pod and taper from about 850 ms p95 to normal over the window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50, approx_quantile(duration,0.95)/1e6 p95 FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('POST','SELECT ts.trip2') GROUP BY 1,2,3",
          "claim": "Travel2's POST clients and DB calls stay fast (about 12 ms p95), so only outbound GET traffic is slowed."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND span_name='GET /api/v1/admintravelservice/admintravel' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "Admin-travel getAllTravels p95 rose to about 1109 ms, as it waits on travel2 admin_trip calls."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='GET /api/v1/admintravelservice/admintravel' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "User-facing ui-dashboard admintravel endpoint p95 rose to about 1120 ms, from about 70 ms normal."
        }
      ]
    }
  ]
}
